"use strict";(globalThis.webpackChunkeo_glossary=globalThis.webpackChunkeo_glossary||[]).push([[59774],{67534(e){e.exports=JSON.parse('{"tag":{"label":"WGCV","permalink":"/eo-glossary/tags/wgcv","allTagsPath":"/eo-glossary/tags","count":168,"items":[{"id":"terms/accuracy","title":"Accuracy","description":"Closeness of agreement between a measured quantity value and a true quantity value of a measurand.","permalink":"/eo-glossary/terms/accuracy"},{"id":"terms/algorithm_theoretical_basis_document","title":"Algorithm Theoretical Basis Document","description":"Document detailing the theoretical foundation of an algorithm, including physical theory, mathematical procedures, and assumptions, updated with algorithm changes.","permalink":"/eo-glossary/terms/algorithm_theoretical_basis_document"},{"id":"terms/analysis","title":"Analysis","description":"Verification method using analytical techniques to demonstrate theoretical compliance with requirements through review, modeling, simulation, calculations, or data comparisons.","permalink":"/eo-glossary/terms/analysis"},{"id":"terms/analysis_ready_data","title":"Analysis Ready Data","description":"Processed data product geometrically referenced and minimally corrected to enable direct use without additional user processing.","permalink":"/eo-glossary/terms/analysis_ready_data"},{"id":"terms/ancillary_data","title":"Ancillary Data","description":"Data acquired on the same platform as the main sensor but not from the sensor itself, used primarily for processing instrument data.","permalink":"/eo-glossary/terms/ancillary_data"},{"id":"terms/area_of_representativeness","title":"Area of Representativeness","description":"Area (or volume) where concentration does not deviate from the station value by more than a specified range.","permalink":"/eo-glossary/terms/area_of_representativeness"},{"id":"terms/artifact","title":"Artifact","description":"- A physical object that is made or modified by human culture - a three-dimensional object held in an archives - a library or archival resource that has value as a physical object in addition to it...","permalink":"/eo-glossary/terms/artifact"},{"id":"terms/attitude_data","title":"Attitude Data","description":"Data representing spacecraft orientation, pointing, calibration, alignment, Euler angles, quaternions, rates, biases, and associated accuracy parameters.","permalink":"/eo-glossary/terms/attitude_data"},{"id":"terms/auxiliary_data","title":"Auxiliary Data","description":"Data enhancing processing and utilization of main sensor data, collected via different processes or platforms, and usable as independent datasets.","permalink":"/eo-glossary/terms/auxiliary_data"},{"id":"terms/band_central_wavelength","title":"Band Central Wavelength","description":"Single wavelength Value within the sensitivity interval of a spectroradiometric Sensor which represents the respective band.","permalink":"/eo-glossary/terms/band_central_wavelength"},{"id":"terms/baseline","title":"Baseline","description":"Reference Period, time or measure against which the Information is assessed or compared.","permalink":"/eo-glossary/terms/baseline"},{"id":"terms/bias","title":"Bias","description":"- measurement bias: estimate of a systematic measurement error - instrument bias: average of replicate indications minus a reference quantity value - estimate of a systematic forecast error.","permalink":"/eo-glossary/terms/bias"},{"id":"terms/bias_correction","title":"Bias correction","description":"Reconciling differences between sensors and/or products by a simple multiplication or addition of a correction factor.","permalink":"/eo-glossary/terms/bias_correction"},{"id":"terms/calibration","title":"Calibration","description":"Process of quantitatively defining a system\'s response to known, controlled inputs using reference measurements.","permalink":"/eo-glossary/terms/calibration"},{"id":"terms/calibration_data","title":"Calibration Data","description":"Data required to calibrate instrument science data, engineering data, and spacecraft data, including pre-flight and in-flight measurements, calibration coefficients, and ground truth.","permalink":"/eo-glossary/terms/calibration_data"},{"id":"terms/characteristic","title":"Characteristic","description":"Distinguishing Feature.","permalink":"/eo-glossary/terms/characteristic"},{"id":"terms/collection","title":"Collection","description":"Group of products that have been processed using a consistent radiometric calibration, geometric registration base, data/metadata format, and version of processing algorithms.","permalink":"/eo-glossary/terms/collection"},{"id":"terms/collection_update","title":"Collection Update","description":"Minor revisions to a relatively small number of products within a collection for the purpose of correcting errors and maintaining consistent quality.","permalink":"/eo-glossary/terms/collection_update"},{"id":"terms/collection_upgrade","title":"Collection Upgrade","description":"New and improved major version of all products within a collection due to comprehensive reprocessing.","permalink":"/eo-glossary/terms/collection_upgrade"},{"id":"terms/confidence_interval","title":"Confidence Interval","description":"Probability that the Quantity lies in the interval, conditioned on the measuring or modelling assumptions.","permalink":"/eo-glossary/terms/confidence_interval"},{"id":"terms/consistency","title":"Consistency","description":"### Notes.","permalink":"/eo-glossary/terms/consistency"},{"id":"terms/continuity","title":"Continuity","description":"### Notes.","permalink":"/eo-glossary/terms/continuity"},{"id":"terms/covariance_matrix","title":"Covariance Matrix","description":"Symmetric positive semi-definite matrix of dimension N \xd7 N associated with an estimate of a real vector quantity of dimension N \xd7 1, containing on its diagonal the squares of the standard uncertain...","permalink":"/eo-glossary/terms/covariance_matrix"},{"id":"terms/data","title":"Data","description":"Value and possibly Uncertainty of a Trait of a specific Entity.","permalink":"/eo-glossary/terms/data"},{"id":"terms/data_fusion","title":"Data fusion","description":"Framework for combining data from multiple sources to produce higher-quality information, with quality defined by application context.","permalink":"/eo-glossary/terms/data_fusion"},{"id":"terms/data_integration","title":"Data Integration","description":"Process of making datasets from different sources compatible through consistent naming, units, and coordinates to enable combined use.","permalink":"/eo-glossary/terms/data_integration"},{"id":"terms/data_maturity","title":"Data Maturity","description":"Beta Products intended to enable users to gain familiarity with the parameters and the data formats. Provisional Product was defined to facilitate data exploration and process studies that do not r...","permalink":"/eo-glossary/terms/data_maturity"},{"id":"terms/data_quality","title":"Data Quality","description":"Metric\u2014such as a number, graph, uncertainty budget, or flag\u2014that enables users to evaluate the fitness for purpose of data or derived products.","permalink":"/eo-glossary/terms/data_quality"},{"id":"terms/data_time_series","title":"Data Time series","description":"A data sequence that is designed to be consistent over a defined time interval.","permalink":"/eo-glossary/terms/data_time_series"},{"id":"terms/dead_band","title":"Dead Band","description":"maximum interval through which a value of a quantity being measured can be changed in both directions without producing a detectable change in the corresponding indication.","permalink":"/eo-glossary/terms/dead_band"},{"id":"terms/derivative_product","title":"Derivative Product","description":"Product additionally processed from baseline or unenhanced mission data.","permalink":"/eo-glossary/terms/derivative_product"},{"id":"terms/derived_products","title":"Derived Products","description":"Higher-level products (level 1b through 4) generated by applying calibration, geo-location transformations, and algorithms to produce sensor units or gridded geophysical parameters.","permalink":"/eo-glossary/terms/derived_products"},{"id":"terms/detection_limit","title":"Detection limit","description":"measured quantity value, obtained by a given measurement procedure, for which the probability of falsely claiming the absence of a component is \u03b2, given a probability \u03b1 of falsely claiming its pres...","permalink":"/eo-glossary/terms/detection_limit"},{"id":"terms/duration","title":"Duration","description":"Non-negative interval Quantity of time equal to the difference between the final and initial instants of a time interval.","permalink":"/eo-glossary/terms/duration"},{"id":"terms/dwell_time","title":"Dwell Time","description":"Time that an antenna beam spends on a target.","permalink":"/eo-glossary/terms/dwell_time"},{"id":"terms/earth_observation","title":"Earth Observation","description":"Science domain dealing with technologies and methods of collecting and analyzing observations about the different Earth spheres.","permalink":"/eo-glossary/terms/earth_observation"},{"id":"terms/earth_observation_based_output","title":"Earth Observation Based Output","description":"Higher-level processing and integration output (indicative level 4 and beyond) that goes beyond basic data processing.","permalink":"/eo-glossary/terms/earth_observation_based_output"},{"id":"terms/earth_observation_product","title":"Earth Observation Product","description":"Direct output from standardized satellite data processing chains (indicative levels 2 and 3), representing fundamental geophysical and biophysical variables.","permalink":"/eo-glossary/terms/earth_observation_product"},{"id":"terms/earth_system_data_record","title":"Earth System Data Record","description":"A unified and coherent set of observations of a given parameter of the Earth system, which is optimized to meet specific requirements in addressing science questions.","permalink":"/eo-glossary/terms/earth_system_data_record"},{"id":"terms/engineering_data","title":"Engineering Data","description":"Data which describe the physical condition and operation of the platform and instruments on the platform.","permalink":"/eo-glossary/terms/engineering_data"},{"id":"terms/entity","title":"Entity","description":"Something that has separate and distinct existence and objective or conceptual reality.","permalink":"/eo-glossary/terms/entity"},{"id":"terms/equivalence","title":"Equivalence","description":"### Notes.","permalink":"/eo-glossary/terms/equivalence"},{"id":"terms/error","title":"Error","description":"Measured quantity value minus a reference quantity value.","permalink":"/eo-glossary/terms/error"},{"id":"terms/expanded_uncertainty","title":"Expanded Uncertainty","description":"Standard Uncertainty multiplied by a coverage factor, k.","permalink":"/eo-glossary/terms/expanded_uncertainty"},{"id":"terms/feature","title":"Feature","description":"Abstraction of real-world phenomena.","permalink":"/eo-glossary/terms/feature"},{"id":"terms/fiducial","title":"Fiducial","description":"used as a fixed standard of reference for comparison or measurement (fiducial point).","permalink":"/eo-glossary/terms/fiducial"},{"id":"terms/fiducial_mark","title":"Fiducial mark","description":"index mark on a test system that allows automatic geometric identification and orientation detection of an object using imaging systems.","permalink":"/eo-glossary/terms/fiducial_mark"},{"id":"terms/fiducial_reference_measurements","title":"Fiducial Reference Measurements","description":"Independent measurements traceable to SI standards, produced with documented uncertainties to validate satellite data.","permalink":"/eo-glossary/terms/fiducial_reference_measurements"},{"id":"terms/field_of_regard","title":"Field-of-regard","description":"an area of the object space scanned by the field-of-view of a scanning sensor.","permalink":"/eo-glossary/terms/field_of_regard"},{"id":"terms/field_of_view","title":"Field-of-view","description":"the solid angle from which the detector receives radiation.","permalink":"/eo-glossary/terms/field_of_view"},{"id":"terms/footprint","title":"Footprint","description":"the area of a target encircled by the field-of-view of a detector of radiation, or irradiated by an active system.","permalink":"/eo-glossary/terms/footprint"},{"id":"terms/fundamental_climate_data_record","title":"Fundamental Climate Data Record","description":"Long-term, stabilised record of calibrated sensor observations in physical units with quantified uncertainty and associated ancillary data.","permalink":"/eo-glossary/terms/fundamental_climate_data_record"},{"id":"terms/fused_product","title":"Fused Product","description":"Derived data product created by merging two or more fully interoperable products into a single, non-reversible dataset.","permalink":"/eo-glossary/terms/fused_product"},{"id":"terms/geodesy","title":"Geodesy","description":"The branch of applied mathematics that deals with the measurement of the shape and area of large tracts of country, the exact position of geographical points, and the curvature, shape, and dimensio...","permalink":"/eo-glossary/terms/geodesy"},{"id":"terms/geolocating","title":"Geolocating","description":"Geopositioning of an Object using a Physical Sensor Model or a True Replacement Model.","permalink":"/eo-glossary/terms/geolocating"},{"id":"terms/geometrical_resolution","title":"Geometrical Resolution","description":"Ability of a sensor system to distinguish signals from neighboring object structures.","permalink":"/eo-glossary/terms/geometrical_resolution"},{"id":"terms/geopositioning","title":"Geopositioning","description":"Determination of the geographic Position of a point (0D) or linear (1D) Feature.","permalink":"/eo-glossary/terms/geopositioning"},{"id":"terms/georectifying","title":"Georectifying","description":"Correcting for positional displacement with respect to the surface of the Earth.","permalink":"/eo-glossary/terms/georectifying"},{"id":"terms/ground_sampling_distance","title":"Ground Sampling Distance","description":"linear distance between pixel centres on the ground.","permalink":"/eo-glossary/terms/ground_sampling_distance"},{"id":"terms/ground_truth","title":"Ground Truth","description":"Geophysical parameter data, measured or collected by other means than by the instrument itself, used as correlative or calibration/validation data for that instrument data.","permalink":"/eo-glossary/terms/ground_truth"},{"id":"terms/homogeneous_data","title":"Homogeneous Data","description":"Data drawn from a single population with constant external influences throughout the observation period.","permalink":"/eo-glossary/terms/homogeneous_data"},{"id":"terms/homogenisation","title":"Homogenisation","description":"Unlike harmonisation, homogenisation is where all satellites are forced to look the same such that when looking at the same location at the same time they would (in theory) give the same signal.","permalink":"/eo-glossary/terms/homogenisation"},{"id":"terms/in_situ_measurement","title":"In Situ Measurement","description":"(1) a direct measurement of the measurand in its original place (2) any sub-orbital measurement of the measurand.","permalink":"/eo-glossary/terms/in_situ_measurement"},{"id":"terms/in-situ_observation","title":"In-Situ Observation","description":"Observations performed in the same Place where a Phenomenon occurs, normally without isolating it from other systems (its environment) or altering its pre-Observation state.","permalink":"/eo-glossary/terms/in-situ_observation"},{"id":"terms/indication","title":"Indication","description":"Quantity value provided by a measuring instrument or a measuring system.","permalink":"/eo-glossary/terms/indication"},{"id":"terms/influence_quantity","title":"Influence quantity","description":"Quantity that affects the relation between the indication and the measurement result without affecting the measured quantity.","permalink":"/eo-glossary/terms/influence_quantity"},{"id":"terms/information","title":"Information","description":"Result of organizing, interpreting, categorizing, or classifying data to assign meaning understandable by the addressee.","permalink":"/eo-glossary/terms/information"},{"id":"terms/instantaneous_field_of_view","title":"Instantaneous Field of View","description":"A measure of the spatial resolution of a remotesensing imaging system.","permalink":"/eo-glossary/terms/instantaneous_field_of_view"},{"id":"terms/instrument","title":"Instrument","description":"Hardware system that collects scientific or operational data, or a hardware-integrated collection of one or more sensors contributing data of one type to an investigation.","permalink":"/eo-glossary/terms/instrument"},{"id":"terms/instrument_calibration","title":"Instrument Calibration","description":"Determination of parameters describing instrument characteristics for generating calibrated and comparable physical values, varying by instrument, mode, and over time due to degradation.","permalink":"/eo-glossary/terms/instrument_calibration"},{"id":"terms/instrument_data","title":"Instrument Data","description":"Data specifically associated with the instrument, either because it was generated by the instrument or included in data packets identified with that instrument.","permalink":"/eo-glossary/terms/instrument_data"},{"id":"terms/instrumental_drift","title":"Instrumental drift","description":"Continuous or incremental change over time in indication, due to changes in metrological properties of a measuring instrument.","permalink":"/eo-glossary/terms/instrumental_drift"},{"id":"terms/interferometric_baseline","title":"Interferometric Baseline","description":"Accurate determination of orbital distances between satellites with compatible orbits, required for SAR and differential interferometry applications.","permalink":"/eo-glossary/terms/interferometric_baseline"},{"id":"terms/interoperable_products","title":"Interoperable Products","description":"Set of two or more ARD products sufficiently documented to enable processing across a continuum of geometric and/or radiometric standards for direct quantitative comparison.","permalink":"/eo-glossary/terms/interoperable_products"},{"id":"terms/laboratory_observation","title":"Laboratory Observation","description":"Usually in-situ observations in which the Object or Phenomenon is isolated from other systems or altered in its original conditions or environment.","permalink":"/eo-glossary/terms/laboratory_observation"},{"id":"terms/location_error","title":"Location Error","description":"Measure of the agreement between the represented Location of an Object and the true Location.","permalink":"/eo-glossary/terms/location_error"},{"id":"terms/measurand","title":"Measurand","description":"Particular Quantity subject to Measurement.","permalink":"/eo-glossary/terms/measurand"},{"id":"terms/measurement","title":"Measurement","description":"Observation of a Quantity.","permalink":"/eo-glossary/terms/measurement"},{"id":"terms/measurement_procedure","title":"Measurement Procedure","description":"Detailed description of a measurement based on one or more principles and methods, including the measurement model and all calculations to obtain a result.","permalink":"/eo-glossary/terms/measurement_procedure"},{"id":"terms/measurement_uncertainty","title":"Measurement Uncertainty","description":"Uncertainty associated with the method of Measurement.","permalink":"/eo-glossary/terms/measurement_uncertainty"},{"id":"terms/methodology","title":"Methodology","description":"A generalised description of an approach or set of approaches to carry out a particular task.","permalink":"/eo-glossary/terms/methodology"},{"id":"terms/model","title":"Model","description":"An, often numeric, theoretical (or otherwise abstract) representation of an Entity intended to generate Data describing one or more of its traits (as a result of pre-set conditions).","permalink":"/eo-glossary/terms/model"},{"id":"terms/monitoring","title":"Monitoring","description":"(1) systematic evaluation over time of some quantity (2) by extension, evaluation over time of the performance of a system, of the occurrence of an event etc.","permalink":"/eo-glossary/terms/monitoring"},{"id":"terms/object","title":"Object","description":"Entity with a well-defined boundary and identity that encapsulates state and behaviour.","permalink":"/eo-glossary/terms/object"},{"id":"terms/observation","title":"Observation","description":"Act of determining the Value of a Property by interacting in a reproducible way with the Phenomenon using a Sensor.","permalink":"/eo-glossary/terms/observation"},{"id":"terms/orbit","title":"Orbit","description":"Path in space described by a satellite revolving around the Earth under mutual gravitational attraction.","permalink":"/eo-glossary/terms/orbit"},{"id":"terms/orbit_prediction_and_determination","title":"Orbit Prediction and Determination","description":"Generation of attitude and state vectors to describe spacecraft position over time, computed either in advance (predicted) or after observation (restituted or precise).","permalink":"/eo-glossary/terms/orbit_prediction_and_determination"},{"id":"terms/parameter","title":"Parameter","description":"A measurable or derived variable occurring in the physical or digital world.","permalink":"/eo-glossary/terms/parameter"},{"id":"terms/phenomenon","title":"Phenomenon","description":"Entity with at least one Property referenced by an identifier.","permalink":"/eo-glossary/terms/phenomenon"},{"id":"terms/platform","title":"Platform","description":"Support carrying instrument(s) or sensor(s), such as a spacecraft, aircraft, or ground-based platform.","permalink":"/eo-glossary/terms/platform"},{"id":"terms/point_to_area_representativeness","title":"Point-to-Area Representativeness","description":"The probability that a point measurement lies within a specific range of area-average (volume-average) concentration value.","permalink":"/eo-glossary/terms/point_to_area_representativeness"},{"id":"terms/positional_accuracy","title":"Positional Accuracy","description":"Closeness of coordinate value to the true or accepted value in a specified reference system.","permalink":"/eo-glossary/terms/positional_accuracy"},{"id":"terms/precise_orbit","title":"Precise Orbit","description":"Orbit model derived from all available satellite tracking data and dynamical corrections, achieving highest accuracy.","permalink":"/eo-glossary/terms/precise_orbit"},{"id":"terms/precision","title":"Precision","description":"Closeness of agreement between indications or measured values obtained by replicate measurements on the same or similar objects under specified conditions.","permalink":"/eo-glossary/terms/precision"},{"id":"terms/predicted_orbit","title":"Predicted Orbit","description":"These state vectors are calculated (e.g.","permalink":"/eo-glossary/terms/predicted_orbit"},{"id":"terms/preliminary_orbit","title":"Preliminary Orbit","description":"Preliminary orbits are based on the fast delivery tracking data.","permalink":"/eo-glossary/terms/preliminary_orbit"},{"id":"terms/primary_data","title":"Primary Data","description":"A set of results from a scientific observation, i.e.","permalink":"/eo-glossary/terms/primary_data"},{"id":"terms/procedure","title":"Procedure","description":"Specified way to carry out an activity or a process.","permalink":"/eo-glossary/terms/procedure"},{"id":"terms/process","title":"Process","description":"Series of activities that interact to produce a result.","permalink":"/eo-glossary/terms/process"},{"id":"terms/process_validation","title":"Process Validation","description":"Established documented evidence providing high assurance that a process consistently produces products meeting predefined specifications and quality characteristics.","permalink":"/eo-glossary/terms/process_validation"},{"id":"terms/processing","title":"Processing","description":"Generation of higher-level products from lower-level and auxiliary products using version-controlled core algorithms supplemented by administrative functions.","permalink":"/eo-glossary/terms/processing"},{"id":"terms/processing_baseline","title":"Processing Baseline","description":"A combination of processor versions, auxiliary data and other needed enablers that allows the generation of a coherent set of EO products.","permalink":"/eo-glossary/terms/processing_baseline"},{"id":"terms/processing_levels","title":"Processing Levels","description":"Raw Data The physical telemetry payload data as received from the satellite, i.e.","permalink":"/eo-glossary/terms/processing_levels"},{"id":"terms/product","title":"Product","description":"Electronic data package distributable to users; content is derived from instrument data via processing involving ancillary and auxiliary data.","permalink":"/eo-glossary/terms/product"},{"id":"terms/product_quality_control","title":"Product Quality Control","description":"Determination of quality parameters for individual products through automated or manual activities such as quick look visualization.","permalink":"/eo-glossary/terms/product_quality_control"},{"id":"terms/product_team","title":"Product Team","description":"Scientifically knowledgeable team ensuring products are generated, high quality, well documented, and delivered to the archive.","permalink":"/eo-glossary/terms/product_team"},{"id":"terms/property","title":"Property","description":"Observable Trait.","permalink":"/eo-glossary/terms/property"},{"id":"terms/quality","title":"Quality","description":"Degree to which a set of inherent characteristics of an object fulfils requirements.","permalink":"/eo-glossary/terms/quality"},{"id":"terms/quality_assessment","title":"Quality Assessment","description":"Derivation of quality indicators sufficient to assess fulfillment of quality requirements.","permalink":"/eo-glossary/terms/quality_assessment"},{"id":"terms/quality_assurance","title":"Quality Assurance","description":"Part of quality management focused on providing confidence that quality requirements will be fulfilled.","permalink":"/eo-glossary/terms/quality_assurance"},{"id":"terms/quality_control","title":"Quality Control","description":"Activities to check and optimize data accuracy and precision after collection; part of quality management focused on fulfilling quality requirements.","permalink":"/eo-glossary/terms/quality_control"},{"id":"terms/quality_indicator","title":"Quality Indicator","description":"Indicator providing sufficient information to allow all users to readily evaluate the fitness for purpose of the data or derived product.","permalink":"/eo-glossary/terms/quality_indicator"},{"id":"terms/quality_information","title":"Quality Information","description":"Secondary data required to assess the primary data set\u2019s fitness for purpose, e.g.","permalink":"/eo-glossary/terms/quality_information"},{"id":"terms/quantity","title":"Quantity","description":"Property having a magnitude that can be expressed as a number from a continuous and contiguous range and a reference.","permalink":"/eo-glossary/terms/quantity"},{"id":"terms/quarantine","title":"Quarantine","description":"Withholding of an Earth observation product from distribution due to severe technical or quality issues.","permalink":"/eo-glossary/terms/quarantine"},{"id":"terms/radiometric_calibration","title":"Radiometric Calibration","description":"Determination of radiometric instrument performance across spatial, spectral, and temporal domains by relating output to true radiometric values.","permalink":"/eo-glossary/terms/radiometric_calibration"},{"id":"terms/random_error","title":"Random Error","description":"Component of measurement error that varies unpredictably in replicate measurements.","permalink":"/eo-glossary/terms/random_error"},{"id":"terms/reference","title":"Reference","description":"Phenomenon whose values for specific properties are known and understood with an Uncertainty significantly lower (quantify?) than that of the Observation with which it is compared.","permalink":"/eo-glossary/terms/reference"},{"id":"terms/relative_standard_uncertainty","title":"Relative Standard Uncertainty","description":"Standard measurement uncertainty divided by the absolute value of the measured quantity value.","permalink":"/eo-glossary/terms/relative_standard_uncertainty"},{"id":"terms/remote_sensing","title":"Remote Sensing","description":"Type of Observation performed at a significant distance from a Phenomenon.","permalink":"/eo-glossary/terms/remote_sensing"},{"id":"terms/repeatability","title":"Repeatability","description":"Measurement precision under conditions including the same procedure, location, equipment, and replicate measurements on similar objects over time.","permalink":"/eo-glossary/terms/repeatability"},{"id":"terms/replicability","title":"Replicability","description":"Property enabling other researchers to conduct an independent study with different data and similar but not identical methods, yet arriving at results that confirm the original study\'s hypothesis.","permalink":"/eo-glossary/terms/replicability"},{"id":"terms/representativeness","title":"Representativeness","description":"Quality or characteristic of a measurement or Observation to accurately represent a specific geographic location, time Period, or environmental condition.","permalink":"/eo-glossary/terms/representativeness"},{"id":"terms/reprocessing","title":"Reprocessing","description":"Systematic generation of a new product revision using archived lower-level products, typically triggered by an improved processing algorithm.","permalink":"/eo-glossary/terms/reprocessing"},{"id":"terms/reproducibility","title":"Reproducibility","description":"Validity of study results through exact reproduction using the same data and methods to verify authenticity.","permalink":"/eo-glossary/terms/reproducibility"},{"id":"terms/resample","title":"Resample","description":"Technique of transforming a digital image to alter resolution, orientation, or sampling points for applications in medical, industrial, and remote sensing contexts.","permalink":"/eo-glossary/terms/resample"},{"id":"terms/research_product","title":"Research Product","description":"A data product produced at a science computing facility by a research algorithm for later migration to a community consensus algorithm and can be archived and distributed by an archive center.","permalink":"/eo-glossary/terms/research_product"},{"id":"terms/resolution","title":"Resolution","description":"### Notes.","permalink":"/eo-glossary/terms/resolution"},{"id":"terms/restituted_orbit","title":"Restituted Orbit","description":"Orbit determination using delayed telemetry data with a one-day latency, computed from a three-day moving window and typically sampled every 60 seconds with lower precision than precise orbits.","permalink":"/eo-glossary/terms/restituted_orbit"},{"id":"terms/sample","title":"Sample","description":"Subset of one or more entities.","permalink":"/eo-glossary/terms/sample"},{"id":"terms/science_data_segment_interface","title":"Science Data Segment Interface","description":"System for assessing and verifying quality of Raw Data Records (RDRs), Sensor Data Records (SDRs), Environmental Data Records (EDRs), and Temperature Data Records (TDRs) through distributed Product...","permalink":"/eo-glossary/terms/science_data_segment_interface"},{"id":"terms/science_stewards","title":"Science Stewards","description":"Experts providing scientific oversight to ensure accurate data and metadata representation, guiding data quality, characterization, and usability requirements.","permalink":"/eo-glossary/terms/science_stewards"},{"id":"terms/secondary_data","title":"Secondary Data","description":"Data used for processing or interpreting primary data.","permalink":"/eo-glossary/terms/secondary_data"},{"id":"terms/segregation","title":"Segregation","description":"Earth observation products with degraded quality relative to nominal standards, such as those acquired during maneuvers or special campaigns, still useful but requiring clear indication of status a...","permalink":"/eo-glossary/terms/segregation"},{"id":"terms/sensitivity_of_a_measuring_system","title":"Sensitivity of a Measuring System","description":"Quotient of the change in an indication of a measuring system and the corresponding change in a value of a quantity being measured. Note: sensitivity can depend on the value of the quantity being m...","permalink":"/eo-glossary/terms/sensitivity_of_a_measuring_system"},{"id":"terms/sensor","title":"Sensor","description":"Device or instrument suited (through physical/chemical interaction) to measure one or more properties of a Phenomenon and thus collect factual/objective data.","permalink":"/eo-glossary/terms/sensor"},{"id":"terms/sensor_performance_monitoring","title":"Sensor Performance Monitoring","description":"Long-term recording and trend analysis of parameters describing sensor quality and their level-0 outputs.","permalink":"/eo-glossary/terms/sensor_performance_monitoring"},{"id":"terms/source_data","title":"Source Data","description":"Data required for producing an Earth observation collection, including unenhanced satellite mission data, precision-corrected Level-1 radiance, or other pre-processed formats meeting program requir...","permalink":"/eo-glossary/terms/source_data"},{"id":"terms/spatial_completeness","title":"Spatial Completeness","description":"Presence or absence of gaps, which are missing values in an otherwise continuous spatial data series.","permalink":"/eo-glossary/terms/spatial_completeness"},{"id":"terms/spatial_consistency","title":"Spatial Consistency","description":"Condition where the spatial statistical properties of the data depend only on the underlying physical processes and not on other factors such as fusing different products or sensors.","permalink":"/eo-glossary/terms/spatial_consistency"},{"id":"terms/spatial_resolution","title":"Spatial Resolution","description":"### Notes.","permalink":"/eo-glossary/terms/spatial_resolution"},{"id":"terms/spectral_band","title":"Spectral Band","description":"Part of the electromagnetic spectrum of specific wavelengths.","permalink":"/eo-glossary/terms/spectral_band"},{"id":"terms/spectral_bandwidth","title":"Spectral Bandwidth","description":"Range of the Spectral Band.","permalink":"/eo-glossary/terms/spectral_bandwidth"},{"id":"terms/spectral_resolution","title":"Spectral Resolution","description":"Measure of the ability to resolve features in the electromagnetic spectrum.","permalink":"/eo-glossary/terms/spectral_resolution"},{"id":"terms/stability","title":"Stability","description":"Maximum acceptable change in Uncertainty per decade.","permalink":"/eo-glossary/terms/stability"},{"id":"terms/standard_uncertainty","title":"Standard Uncertainty","description":"Standard deviation of the probability distribution describing the spread of possible values in quantitative/continuous data.","permalink":"/eo-glossary/terms/standard_uncertainty"},{"id":"terms/standardisation","title":"Standardisation","description":"Establish an agreement (not necessarily obligatory) on precise procedures and concepts.","permalink":"/eo-glossary/terms/standardisation"},{"id":"terms/structured_error","title":"Structured Error","description":"Errors in satellite imagery affecting multiple pixels non-uniformly, where errors are correlated across affected regions due to localized systematic or random effects.","permalink":"/eo-glossary/terms/structured_error"},{"id":"terms/swath","title":"Swath","description":"Area covered by spatial samples collected during a scan of a spaceborne instrument, determined by its incidence angle.","permalink":"/eo-glossary/terms/swath"},{"id":"terms/system","title":"System","description":"Set of interrelated or interacting elements.","permalink":"/eo-glossary/terms/system"},{"id":"terms/systematic_error","title":"Systematic Error","description":"Component of measurement error that remains constant or varies predictably across replicate measurements.","permalink":"/eo-glossary/terms/systematic_error"},{"id":"terms/temporal_consistency","title":"Temporal Consistency","description":"Condition where the temporal statistical properties of the Sample depend only on the underlying physical processes and not on other factors such as fusing different products or sensors.","permalink":"/eo-glossary/terms/temporal_consistency"},{"id":"terms/temporal_resolution","title":"Temporal Resolution","description":"Regular interval between observations or model time steps that determines the smallest resolvable event or process.","permalink":"/eo-glossary/terms/temporal_resolution"},{"id":"terms/temporal_revisit","title":"Temporal Revisit","description":"Interval between successive observations.","permalink":"/eo-glossary/terms/temporal_revisit"},{"id":"terms/thematic_uncertainty","title":"Thematic Uncertainty","description":"Uncertainty associated with the method of classification.","permalink":"/eo-glossary/terms/thematic_uncertainty"},{"id":"terms/tolerance","title":"Tolerance","description":"### Notes.","permalink":"/eo-glossary/terms/tolerance"},{"id":"terms/traceability","title":"Traceability","description":"Property of a measurement result whereby the result can be related to a Reference through a documented unbroken chain of calibrations, each contributing to the measurement uncertainty.","permalink":"/eo-glossary/terms/traceability"},{"id":"terms/traceability_chain","title":"Traceability Chain","description":"Sequence of measurement standards and calibrations that is used to relate a measurement result to a reference.","permalink":"/eo-glossary/terms/traceability_chain"},{"id":"terms/trait","title":"Trait","description":"Characteristic belonging to an entity and referenced by an identifier.","permalink":"/eo-glossary/terms/trait"},{"id":"terms/type_a_evaluation_of_uncertainty","title":"Type A evaluation of uncertainty","description":"Method of evaluation of a component of measurement uncertainty by a statistical analysis of quantity values obtained by measurements under repeatability conditions.","permalink":"/eo-glossary/terms/type_a_evaluation_of_uncertainty"},{"id":"terms/type_b_evaluation_of_uncertainty","title":"Type B evaluation of uncertainty","description":"Method of evaluation of a component of measurement uncertainty by means other than a statistical analysis of quantity values obtained by measurement.","permalink":"/eo-glossary/terms/type_b_evaluation_of_uncertainty"},{"id":"terms/uncertainty","title":"Uncertainty","description":"Parameter, associated with the result of a measurement, that characterises the dispersion of the values that could reasonably be attributed to the measurand.","permalink":"/eo-glossary/terms/uncertainty"},{"id":"terms/uncertainty_of_measurement_method","title":"Uncertainty of Measurement Method","description":"Uncertainty associated with the method of measurement, as there can be other methods, some of them as yet unknown or in some way impractical, that would give systematically different results of app...","permalink":"/eo-glossary/terms/uncertainty_of_measurement_method"},{"id":"terms/validation","title":"Validation","description":"Process of assessing, by independent means, the quality of the data products derived from the system outputs.","permalink":"/eo-glossary/terms/validation"},{"id":"terms/value","title":"Value","description":"Element of a type domain.","permalink":"/eo-glossary/terms/value"},{"id":"terms/variable","title":"Variable","description":"Physical property whose value determines the characteristics or behavior of a system, such as temperature, pressure, or density.","permalink":"/eo-glossary/terms/variable"},{"id":"terms/verification","title":"Verification","description":"Provision of objective evidence that a given item fulfils specified requirements.","permalink":"/eo-glossary/terms/verification"},{"id":"terms/vicarious_calibration","title":"Vicarious Calibration","description":"Post-launch calibration of sensors that make use of natural or artificial sites on the surface of the Earth.","permalink":"/eo-glossary/terms/vicarious_calibration"}],"unlisted":false}}')}}]);